// ============================================================
// js/data/command_stories.js
// 指令专属剧情库 v2 — 多层级分支系统
//
// 【结构说明】
// COMMAND_STORIES['指令名'] = {
//   stages: [
//     {
//       affRange: [min, max],           // 好感度范围（包含min，不含max；用Infinity表示无上限）
//       branches: {                      // 性格分支（用正则匹配角色personality）
//         '高傲|傲娇':  [ story1, story2, ... ],   // 匹配高傲或傲娇性格
//         '温柔|温和':  [ story1, story2, ... ],   // 匹配温柔或温和
//         '冷漠|无口':  [ ... ],
//         '活泼|开朗|元气': [ ... ],
//         '_default':   [ story1, story2, ... ],   // 无匹配时的默认分支
//       }
//     },
//   ]
// }
//
// 每个 story 对象：
// {
//   story: ['段落1', '段落2', ...],    // 剧情文本
//   effects: { lust: 5, obedience: 3, affection: 1 },   // 属性加成
//   expChanges: { expV: 1, expLove: 2 },                // 经验变化（可选）
// }
//
// 【经验变化系统 expChanges】
// ★ 支持中文键名！可以直接写中文，也可以用英文。
//
// 方式一：简写（只给奴隶加经验）
//   expChanges: { 'V经验': 2, '口交经验': 1 }
//   或者：expChanges: { expV: 2, expOral: 1 }
//
// 方式二：完整格式（分别指定奴隶和玩家经验）
//   expChanges: {
//     slave:  { 'V经验': 2, '口交经验': 1 },    // 奴隶经验
//     player: { '爱抚经验': 1, '调教经验': 1 },  // 玩家经验
//   }
//
// 中文键名对照表：
//   V经验 A经验 绝顶经验 射精经验 性交经验 内射经验
//   口交经验 爱情经验 紧缚经验 调教经验 肛射经验
//   U经验 M经验 自慰经验 爱抚经验 接吻经验
//   道具经验 露出经验 束缚经验
//
//
// 【占位符系统】
//   {slave}    → 奴隶的名字（如"优茗"）
//   {master}   → 主人的称呼（根据人称设置：我/你/主人名字）
//   {masterD}  → 主人的"的"（我的/你的/XXX的）
//   {ta}       → 他/她（根据奴隶性别）
//   {tade}     → 他的/她的
//
// 【如何添加新剧情】
// 1. 找到对应指令名（如'爱抚'）
// 2. 找到对应好感度段 affRange
// 3. 找到对应性格分支（如'温柔|温和'），或 '_default'
// 4. 在该数组中新增一个 { story, effects, expChanges } 对象
//    系统会从该数组中随机抽取一条播放
//
// 【如何添加新指令】直接在 COMMAND_STORIES 对象中添加新键值对即可。
// ============================================================

