// ============================================================
// 【完整写作指南 & 双方经验示例】
// ============================================================
//
// ═══ affRange 好感度匹配规则 ═══
// 
// 系统会自动将旧的raw值范围转换为等级匹配：
//   affRange: [0, 30]      → 匹配 好感Lv.1~2（低好感）
//   affRange: [30, 70]     → 匹配 好感Lv.3~5（中好感）  
//   affRange: [70, Infinity] → 匹配 好感Lv.6~10（高好感）
//
// 也可以直接用等级数字（更直观）：
//   affRange: [1, 3]       → Lv.1~2
//   affRange: [3, 6]       → Lv.3~5
//   affRange: [6, 11]      → Lv.6~10
//
// ═══ expChanges 双方经验写法 ═══
//
// 【写法一】简写：只给奴隶加经验
//   expChanges: { 'V经验': 2 }
//
// 【写法二】完整：分别指定双方经验
//   expChanges: {
//     slave:  { 'V经验': 2, '口交经验': 1 },
//     player: { '爱抚经验': 1, '调教经验': 1 },
//   }
//
// ═══ 中文经验键名对照 ═══
//   V经验 A经验 绝顶经验 射精经验 性交经验 内射经验
//   口交经验 爱情经验 紧缚经验 调教经验 肛射经验
//   U经验 M经验 自慰经验 爱抚经验 接吻经验
//   道具经验 露出经验 束缚经验
//
// ═══ 完整双方经验示例 ═══

